from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-020_Q1"
EVENT_ID = "CSX-020"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
QUESTION_PATH = TASK_DIR / "question_en.md"
