            "hdd35_c_day": metrics["hdd35_c_day"],
            "days_ge35c": metrics["days_ge35c"],
            "days_ge40c": metrics["days_ge40c"],
            "longest_ge35c_run": metrics["longest_ge35c_run"],
            "peak_tmax": metrics["peak_tmax"],
            "population": metrics["population"],
            "p_hdd35_per_100k": metrics["p_hdd35_per_100k"],
            "precip_max_mm": metrics["precip_max_mm"],
