            "peak_tmax_c": 0.1,
            "precip_max_mm": 0.1,
            "mean_dnbr": 0.0001,
            "mean_embedding_change": 0.0001,
            "integer_counts": 0,
            "dates": "exact",
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final classification and heat score",
                    "points": 4,
                    "description": "Gives persistent_heat_exposure and 4/4.",
                    "partial_credit": "Credit a heat label without the exact score, or a score with one incorrect component.",
                },
                {
                    "name": "Heat-load formulas and numeric values",
                    "points": 5,
                    "description": "Applies HDD35, reports 36.9 C days, 2 days at or above 40 C, the 6-day run, and P_HDD35 of 127.2.",
                    "partial_credit": "Credit correct formulas with rounding drift or one missing value.",
                },
                {
