                    "points": 3,
                    "description": "Marks rainfall_centered false using 21.9 mm below 50 mm and broad_surface_change false using 0.0361 mean dNBR and 0.0300 mean embedding change below threshold.",
                    "partial_credit": "Credit one correctly justified flag.",
                },
                {
                    "name": "Peak and event-window extraction",
                    "points": 2,
                    "description": "Reports 42.2 C on 2020-01-04 and the 2019-12-27 to 2020-01-01 hot-run window.",
                    "partial_credit": "Credit correct values without dates.",
                },
                {
