                    "partial_credit": "Credit a mostly complete JSON with minor formatting issues.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "audit": audit,
    }


def main() -> None:
    result = build_payload()
    apply_deepened_task_frame(result)
    OUTPUT_PATH.write_text(
        json.dumps(result, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
